	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("round trip changed the graph\n got: %#v\nwant: %#v", got, want)
	}
	again, err := json.Marshal(got)
	if err != nil {
		t.Fatal(err)
	}
	if string(again) != string(data) {
		t.Fatalf("second encoding differs\n%s\n%s", data, again)
	}
