		`{"kind":"loop","id":"loop.rounds"`,
		`{"kind":"scope","id":"scope.round"`,
		`{"kind":"condition","id":"cond.validation"`,
		`{"kind":"command","id":"cmd.validation"`,
		`{"kind":"exit","id":"exit.continue"`,
		`{"kind":"group","id":"group.checks"`,
		`{"kind":"sequence","id":"helper.summary"`,
		`"statement":"continue"`,
		`"target":"call.coder"`,
