	empty, err := json.Marshal(Graph{Body: Sequence{Body: []Operation{Group{}}}})
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{`"sessions":[]`, `"diagnostics":[]`, `"supervision":[]`, `"children":[]`} {
